#!/usr/bin/env python3
"""Payroll summary: python3 payroll.py INPUT_DIR OUTPUT_FILE (see /app/docs)."""
import csv
import gzip
import io
import json
import os
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


# ----------------------------------------------------------------- helpers
def read_bytes(path):
    with open(path, "rb") as f:
        data = f.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data


def read_text(path):
    text = read_bytes(path).decode("utf-8-sig")
    return text


def csv_rows(text, delimiter=","):
    rows = []
    for row in csv.reader(io.StringIO(text, newline=""), delimiter=delimiter):
        if not row or all(not c.strip() for c in row):
            continue
        rows.append(row)
    return rows


def list_files(d):
    out = []
    if not os.path.isdir(d):
        return out
    for root, _dirs, files in os.walk(d):
        for f in files:
            out.append(os.path.join(root, f))
    return sorted(out)


def local_to_epoch(tz, naive, dst=None):
    """Instant (int seconds) of a local wall-clock time.

    dst: None -> first occurrence of a repeated time; True/False -> choose the
    occurrence with/without daylight saving time."""
    first = naive.replace(tzinfo=tz, fold=0)
    second = naive.replace(tzinfo=tz, fold=1)
    o1, o2 = first.utcoffset(), second.utcoffset()
    chosen = first
    if o1 != o2:
        # ambiguous (repeated) or non-existent time
        d1 = first.dst()
        if d1 is not None and d1 > timedelta(0) and (second.dst() or timedelta(0)) == timedelta(0) \
                and o1 > o2:
            # repeated hour: fold 0 is DST, fold 1 is standard
            if dst is False:
                chosen = second
        elif o1 > o2 and dst is False:
            chosen = second
    return to_epoch(chosen)


def to_epoch(dt):
    d = dt - EPOCH
    return d.days * 86400 + d.seconds


def epoch_dt(ts, tz):
    return datetime.fromtimestamp(ts, tz)


def parse_iso(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return dt


def std_offset(tz, ts):
    dt = datetime.fromtimestamp(ts, tz)
    return dt.utcoffset() - (dt.dst() or timedelta(0))


def norm_dir(s):
    s = s.strip().upper()
    if s in ("IN", "CLOCK_IN", "I", "K"):
        return "IN"
    if s in ("OUT", "CLOCK_OUT", "O", "G"):
        return "OUT"
    raise ValueError("bad direction %r" % s)


def dst_flag(abbr):
    a = abbr.strip().upper()
    if a.endswith("DT"):
        return True
    if a.endswith("ST"):
        return False
    return None


# ----------------------------------------------------------------- readers
# each reader yields (punch_id, employee, direction, epoch_seconds)
def read_abbr_csv(path, tz):
    header = None
    known = {"Badge", "Punch", "Date", "Time", "Zone", "Terminal", "Record"}
    for row in csv_rows(read_text(path)):
        cells = [c.strip() for c in row]
        if "Badge" in cells and "Record" in cells and "Punch" in cells:
            header = {name: i for i, name in enumerate(cells)}
            continue
        if header is None:
            continue

        def g(name):
            i = header.get(name)
            return cells[i] if i is not None and i < len(cells) else ""

        m, d, y = g("Date").split("/")
        t = g("Time").upper()
        ampm = None
        if t.endswith("AM") or t.endswith("PM"):
            ampm = t[-2:]
            t = t[:-2].strip()
        hh, mm, ss = (int(x) for x in t.split(":"))
        if ampm:
            hh = hh % 12
            if ampm == "PM":
                hh += 12
        naive = datetime(int(y), int(m), int(d), hh, mm, ss)
        ts = local_to_epoch(tz, naive, dst_flag(g("Zone")))
        yield g("Record"), g("Badge"), norm_dir(g("Punch")), ts


def read_epoch_jsonl(path, tz):
    schema = 1
    for line in read_text(path).splitlines():
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        if not isinstance(obj, dict):
            continue
        if "schema" in obj and "id" not in obj and "punch_id" not in obj:
            schema = int(obj["schema"])
            continue
        if obj.get("heartbeat") is True:
            continue
        if schema == 2:
            pid, emp, d = obj["punch_id"], obj["employee"], obj["direction"]
            ts = int(obj["epoch_ms"]) // 1000
        else:
            pid, emp, d = obj["id"], obj["emp"], obj["dir"]
            if "ts_ms" in obj:
                ts = int(obj["ts_ms"]) // 1000
            else:
                ts = int(obj["ts"])
        yield str(pid), str(emp).strip(), norm_dir(d), ts


def read_offset_csv(path, tz):
    header = None
    for row in csv_rows(read_text(path), ";"):
        cells = [c.strip() for c in row]
        if "punch_id" in cells and "timestamp" in cells:
            header = {n: i for i, n in enumerate(cells)}
            continue
        if header is None:
            continue
        pid = cells[header["punch_id"]]
        emp = cells[header["employee"]]
        ev = cells[header["event"]]
        ts = to_epoch(parse_iso(cells[header["timestamp"]]))
        yield pid, emp, norm_dir(ev), ts


def read_legacy_fixed(path, tz):
    offset = None
    for raw in read_text(path).split("\n"):
        line = raw.rstrip("\r")
        if not line.strip():
            continue
        rt = line[0]
        if rt == "H":
            off = line[13:18].strip()
            if off and off[0] in "+-" and len(off) == 5:
                sign = 1 if off[0] == "+" else -1
                offset = sign * (int(off[1:3]) * 3600 + int(off[3:5]) * 60)
            else:
                offset = None
        elif rt == "D":
            pid = line[1:9]
            badge = line[9:15].strip()
            d = "IN" if line[15] == "I" else "OUT"
            stamp = line[16:30]
            naive = datetime(int(stamp[0:4]), int(stamp[4:6]), int(stamp[6:8]),
                             int(stamp[8:10]), int(stamp[10:12]), int(stamp[12:14]))
            as_utc = to_epoch(naive.replace(tzinfo=UTC))
            if offset is None:
                # site standard offset (constant apart from historic changes);
                # evaluate at the approximate instant
                off_s = std_offset(tz, as_utc)
                off_s = int(off_s.total_seconds())
                ts = as_utc - off_s
                # refine in case the standard offset differs at the true instant
                off2 = int(std_offset(tz, ts).total_seconds())
                if off2 != off_s:
                    ts = as_utc - off2
            else:
                ts = as_utc - offset
            yield pid, "E" + badge, d, ts


def read_de_tsv(path, tz):
    header = None
    for row in csv_rows(read_text(path), "\t"):
        cells = [c.strip() for c in row]
        if "Ausweis" in cells and "Buchung" in cells:
            header = {n: i for i, n in enumerate(cells)}
            continue
        if header is None:
            continue

        def g(name):
            return cells[header[name]]

        dd, mo, yy = g("Datum").split(".")
        hh, mm = g("Uhrzeit").split(":")[:2]
        naive = datetime(int(yy), int(mo), int(dd), int(hh), int(mm))
        z = g("Zeitzone").upper()
        flag = True if z == "MESZ" else (False if z == "MEZ" else None)
        ts = local_to_epoch(tz, naive, flag)
        yield g("Nr"), g("Ausweis"), norm_dir(g("Buchung")), ts


def read_local_csv(path, tz):
    header = None
    for row in csv_rows(read_text(path)):
        cells = [c.strip() for c in row]
        if "employee_id" in cells and "punch_ref" in cells:
            header = {n: i for i, n in enumerate(cells)}
            continue
        if header is None:
            continue
        naive = datetime.strptime(cells[header["local_time"]], "%Y-%m-%d %H:%M:%S")
        ts = local_to_epoch(tz, naive, None)
        yield (cells[header["punch_ref"]], cells[header["employee_id"]],
               norm_dir(cells[header["direction"]]), ts)


def read_local_jsonl(path, tz):
    for line in read_text(path).splitlines():
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        p = obj.get("punch") if isinstance(obj, dict) else None
        if not isinstance(p, dict):
            continue
        pid = p["id"]
        pid = str(int(pid)) if isinstance(pid, (int, float)) else str(pid).strip()
        naive = datetime.strptime(p["at"].strip(), "%Y-%m-%d %H:%M:%S")
        yield pid, str(p["badge"]).strip(), norm_dir(p["type"]), local_to_epoch(tz, naive, None)


READERS = {
    "abbr-csv": read_abbr_csv,
    "epoch-jsonl": read_epoch_jsonl,
    "offset-csv": read_offset_csv,
    "legacy-fixed": read_legacy_fixed,
    "de-tsv": read_de_tsv,
    "local-csv": read_local_csv,
    "local-jsonl": read_local_jsonl,
}


# ----------------------------------------------------------------- main
def main(inp, outp):
    with open(os.path.join(inp, "period.json")) as f:
        period = json.load(f)
    p_start = date.fromisoformat(period["start"])
    p_end = date.fromisoformat(period["end"])
    cutoff = to_epoch(parse_iso(period["corrections_cutoff"]))

    sites = {}
    for row in csv.DictReader(io.StringIO(read_text(os.path.join(inp, "sites.csv")), newline="")):
        sites[row["site"].strip()] = (ZoneInfo(row["timezone"].strip()), row["format"].strip())

    employees = {}
    for row in csv.DictReader(io.StringIO(read_text(os.path.join(inp, "employees.csv")), newline="")):
        employees[row["employee_id"].strip()] = row["home_site"].strip()

    rates = {}
    for row in csv.DictReader(io.StringIO(read_text(os.path.join(inp, "rates.csv")), newline="")):
        rates.setdefault(row["employee_id"].strip(), []).append(
            (date.fromisoformat(row["effective_from"].strip()), Decimal(row["hourly_rate"].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}  # (site, id) -> [employee, direction, ts]
    ever = set()
    for site, (tz, fmt) in sorted(sites.items()):
        reader = READERS[fmt]
        for path in list_files(os.path.join(inp, "exports", site)):
            for pid, emp, d, ts in reader(path, tz):
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = [emp, d, ts]

    # 2. corrections
    corr = []
    for path in list_files(os.path.join(inp, "corrections")):
        for row in csv.DictReader(io.StringIO(read_text(path), newline="")):
            if not row or not (row.get("correction_id") or "").strip():
                continue
            row = {k: (v or "").strip() for k, v in row.items() if k is not None}
            row["_issued"] = to_epoch(parse_iso(row["issued_at"]))
            corr.append(row)
    corr = [c for c in corr if c["_issued"] <= cutoff]
    corr.sort(key=lambda c: (c["_issued"], c["correction_id"]))
    voided = set()
    applied = 0
    for c in corr:
        key = (c["site"], c["punch_id"])
        act = c["action"].lower()
        if act == "void":
            if key in punches and key not in voided:
                voided.add(key)
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches and key not in voided:
                punches[key][2] = to_epoch(parse_iso(c["time"]))
                applied += 1
        elif act == "add":
            if key not in ever:
                ever.add(key)
                punches[key] = [c["employee"], norm_dir(c["type"]), to_epoch(parse_iso(c["time"]))]
                applied += 1

    # group by employee, discard unknown badges
    by_emp = {}
    for (site, pid), (emp, d, ts) in punches.items():
        if emp not in employees:
            continue
        by_emp.setdefault(emp, []).append((ts, 0 if d == "OUT" else 1, site, pid, d))

    def round_ts(ts, tz):
        off = int(epoch_dt(ts, tz).utcoffset().total_seconds())
        local = ts + off
        r = ((local + 180) // 360) * 360
        return ts + (r - local)

    def workday(rts, hz):
        return epoch_dt(rts, hz).date()

    res = {e: dict(shifts=0, paid=0, ot=0, night=0, gross=Fraction(0)) for e in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    for emp, plist in by_emp.items():
        hz = sites[employees[emp]][0]
        plist.sort(key=lambda p: (p[0], p[1], p[2], p[3]))
        kept = []
        for ts, _o, site, pid, d in plist:
            tz = sites[site][0]
            rts = round_ts(ts, tz)
            if kept and kept[-1][4] == d and 0 <= ts - kept[-1][0] <= 300:
                if p_start <= workday(rts, hz) <= p_end:
                    exc["duplicates_dropped"] += 1
                continue
            kept.append((ts, site, pid, rts, d))

        shifts = []  # (in_rts, out_rts, site, workday)
        i = 0
        pending = None
        for ts, site, pid, rts, d in kept:
            if d == "IN":
                if pending is not None:
                    if p_start <= workday(pending[1], hz) <= p_end:
                        exc["open_shifts"] += 1
                pending = (site, rts)
            else:
                if pending is not None and 0 <= rts - pending[1] <= 16 * 3600:
                    shifts.append((pending[1], rts, pending[0], workday(pending[1], hz)))
                    pending = None
                else:
                    if pending is not None:
                        if p_start <= workday(pending[1], hz) <= p_end:
                            exc["open_shifts"] += 1
                        pending = None
                    if p_start <= workday(rts, hz) <= p_end:
                        exc["orphan_outs"] += 1
        if pending is not None and p_start <= workday(pending[1], hz) <= p_end:
            exc["open_shifts"] += 1

        shifts = [s for s in shifts if p_start <= s[3] <= p_end]
        shifts.sort(key=lambda s: s[0])
        day_paid = {}
        week_paid = {}
        r = res[emp]
        for in_t, out_t, site, wd in shifts:
            tz = sites[site][0]
            worked = max(0, (out_t - in_t) // 60)
            paid = worked - 30 if worked > 360 else worked
            # night minutes
            night = 0
            cache = {}
            t = in_t
            while t < out_t:
                b = t // 900
                if b not in cache:
                    cache[b] = int(epoch_dt(t, tz).utcoffset().total_seconds())
                lh = ((t + cache[b]) // 3600) % 24
                if lh >= 22 or lh < 6:
                    night += 1
                t += 60
            night = min(night, paid)
            # overtime
            before = day_paid.get(wd, 0)
            day_paid[wd] = before + paid
            daily_ot = max(0, before + paid - 480) - max(0, before - 480)
            monday = wd - timedelta(days=wd.weekday())
            wb = week_paid.get(monday, 0)
            nd = paid - daily_ot
            week_paid[monday] = wb + nd
            weekly_ot = max(0, wb + nd - 2400) - max(0, wb - 2400)
            ot = daily_ot + weekly_ot
            regular = paid - ot
            rate = None
            for eff, rt in rates.get(emp, []):
                if eff <= wd:
                    rate = rt
            if rate is None:
                lst = rates.get(emp)
                rate = lst[0][1] if lst else Decimal(0)
            rate = Fraction(rate)
            pay = rate * (Fraction(regular) + Fraction(3, 2) * ot) / 60 \
                + rate * Fraction(15, 100) * night / 60
            r["shifts"] += 1
            r["paid"] += paid
            r["ot"] += ot
            r["night"] += night
            r["gross"] += pay

    def cents(fr):
        return int((fr * 100 + Fraction(1, 2)) // 1)

    def money(c):
        return "%d.%02d" % divmod(c, 100)

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=0)
    for e in sorted(employees):
        r = res[e]
        c = cents(r["gross"])
        out_emps[e] = {"shifts": r["shifts"], "paid_minutes": r["paid"],
                       "overtime_minutes": r["ot"], "night_minutes": r["night"],
                       "gross": money(c)}
        tot["shifts"] += r["shifts"]
        tot["paid_minutes"] += r["paid"]
        tot["overtime_minutes"] += r["ot"]
        tot["night_minutes"] += r["night"]
        tot["gross"] += c
    tot["gross"] = money(tot["gross"])
    result = {"period": {"start": period["start"], "end": period["end"]},
              "employees": out_emps, "exceptions": exc, "totals": tot}
    d = os.path.dirname(os.path.abspath(outp))
    os.makedirs(d, exist_ok=True)
    with open(outp, "w") as f:
        json.dump(result, f, indent=1)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
